/* Hidden attribute priority override */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #2b1f3d;
  --color-panel: #473b64;
  --color-wood: #8f563b;
  --color-wood-dark: #663926;
  --color-wood-light: #df7126;
  --color-gold: #fbf236;
  --color-light: #f4f4f4;
  --color-dark: #1b1226;
  --color-accent: #696a6a;
  --pixel-shadow: 4px 4px 0px #110d18;
  --pixel-border: 4px solid #110d18;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-light);
  font-family: 'Courier New', Courier, monospace, system-ui;
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.shelf-app {
  width: 100%;
  max-width: 760px;
  background: var(--color-panel);
  border: var(--pixel-border);
  box-shadow: 8px 8px 0px #110d18;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header {
  text-align: center;
  border-bottom: 4px dashed #663926;
  padding-bottom: 12px;
}

.app-title {
  font-size: 1.75rem;
  letter-spacing: 2px;
  color: var(--color-gold);
  text-shadow: 2px 2px 0px #110d18;
}

.app-subtitle {
  font-size: 1rem;
  color: #d0c8e0;
  margin-top: 4px;
}

.controls-card {
  background: #362c4e;
  border: var(--pixel-border);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.controls-row {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.control-group {
  display: flex;
  flex-direction: column;
  flex: 1 1 160px;
  gap: 6px;
}

.search-group {
  flex: 1 1 100%;
}

.toggle-group {
  flex: 0 1 120px;
}

.pixel-label {
  font-weight: bold;
  font-size: 0.95rem;
  color: var(--color-gold);
  text-shadow: 1px 1px 0px #110d18;
}

.pixel-input,
.pixel-select,
.pixel-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 10px 12px;
  color: var(--color-light);
  background: #231c33;
  border: 3px solid #110d18;
  box-shadow: 2px 2px 0px #110d18;
  border-radius: 0;
  outline: none;
  transition: transform 0.05s ease, background 0.1s ease;
}

.pixel-input:focus,
.pixel-select:focus,
.pixel-btn:focus {
  background: #1b1226;
  border-color: var(--color-gold);
  box-shadow: 0 0 0 2px var(--color-gold);
}

.pixel-btn {
  cursor: pointer;
  background: var(--color-wood);
  color: #fff;
  text-align: center;
}

.pixel-btn:hover {
  background: var(--color-wood-light);
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 0 0 0;
}

.shelf-display {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.shelf-header-status {
  font-size: 0.9rem;
  font-weight: bold;
  color: #d0c8e0;
}

.books-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 16px;
  min-height: 220px;
  align-items: end;
}

.shelf-plank {
  height: 18px;
  background: var(--color-wood);
  border-top: 4px solid var(--color-wood-light);
  border-bottom: 4px solid var(--color-wood-dark);
  box-shadow: 0 4px 0 #110d18;
  margin-top: 4px;
}

.book-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 190px;
  padding: 12px 10px;
  background-color: var(--book-color, #4b692f);
  border: 3px solid #110d18;
  box-shadow: 3px 3px 0px #110d18;
  color: #fff;
  position: relative;
  user-select: none;
}

.book-card::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 0;
  bottom: 0;
  width: 4px;
  background: rgba(255, 255, 255, 0.25);
}

.book-card::after {
  content: "";
  position: absolute;
  left: 10px;
  top: 0;
  bottom: 0;
  width: 2px;
  background: rgba(0, 0, 0, 0.35);
}

.book-content {
  margin-left: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.book-title {
  font-size: 0.95rem;
  line-height: 1.25;
  font-weight: bold;
  word-break: break-word;
  color: #fff;
  text-shadow: 1px 1px 0px #110d18;
}

.book-author {
  font-size: 0.8rem;
  color: #f7e3af;
  word-break: break-word;
}

.book-year {
  font-size: 0.8rem;
  font-weight: bold;
  align-self: flex-end;
  background: #110d18;
  color: var(--color-gold);
  padding: 2px 6px;
  border: 1px solid var(--color-gold);
  margin-top: 8px;
}

.empty-notice {
  padding: 32px 16px;
  text-align: center;
  background: #231c33;
  border: 3px dashed var(--color-gold);
  color: var(--color-gold);
  font-weight: bold;
  font-size: 1.1rem;
}

@media (max-width: 480px) {
  .shelf-app {
    padding: 16px;
  }
  .books-grid {
    grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
    gap: 12px;
  }
  .toggle-group {
    flex: 1 1 100%;
  }
}

const BOOKS = [
  {
    id: 1,
    title: "Dune",
    author: "Frank Herbert",
    year: 1965,
    color: "#b86f50"
  },
  {
    id: 2,
    title: "1984",
    author: "George Orwell",
    year: 1949,
    color: "#3b5e8c"
  },
  {
    id: 3,
    title: "Neuromancer",
    author: "William Gibson",
    year: 1984,
    color: "#3f784c"
  },
  {
    id: 4,
    title: "Snow Crash",
    author: "Neal Stephenson",
    year: 1992,
    color: "#804173"
  },
  {
    id: 5,
    title: "Fahrenheit 451",
    author: "Ray Bradbury",
    year: 1953,
    color: "#a63d40"
  },
  {
    id: 6,
    title: "Solaris",
    author: "Stanislaw Lem",
    year: 1961,
    color: "#386c75"
  },
  {
    id: 7,
    title: "Foundation",
    author: "Isaac Asimov",
    year: 1951,
    color: "#6a5182"
  },
  {
    id: 8,
    title: "Hyperion",
    author: "Dan Simmons",
    year: 1989,
    color: "#8c6d3b"
  }
];

const state = {
  searchQuery: "",
  sortBy: "title",
  ascending: true
};

const searchInput = document.getElementById("search-input");
const sortSelect = document.getElementById("sort-select");
const orderToggle = document.getElementById("order-toggle");
const booksContainer = document.getElementById("books-container");
const emptyNotice = document.getElementById("empty-notice");
const statusMessage = document.getElementById("status-message");

function renderBooks() {
  const query = state.searchQuery.trim().toLowerCase();

  const filtered = BOOKS.filter((book) => {
    if (!query) return true;
    const titleMatch = book.title.toLowerCase().includes(query);
    const authorMatch = book.author.toLowerCase().includes(query);
    return titleMatch || authorMatch;
  });

  filtered.sort((a, b) => {
    let valA = a[state.sortBy];
    let valB = b[state.sortBy];

    if (typeof valA === "string") {
      valA = valA.toLowerCase();
      valB = valB.toLowerCase();
      const cmp = valA.localeCompare(valB);
      return state.ascending ? cmp : -cmp;
    }

    return state.ascending ? valA - valB : valB - valA;
  });

  booksContainer.innerHTML = "";

  if (filtered.length === 0) {
    emptyNotice.removeAttribute("hidden");
    statusMessage.textContent = "No matching books found.";
  } else {
    emptyNotice.setAttribute("hidden", "");
    statusMessage.textContent = `Showing ${filtered.length} of ${BOOKS.length} books`;

    filtered.forEach((book) => {
      const card = document.createElement("article");
      card.className = "book-card";
      card.setAttribute("role", "listitem");
      card.style.setProperty("--book-color", book.color);

      const contentDiv = document.createElement("div");
      contentDiv.className = "book-content";

      const titleEl = document.createElement("h2");
      titleEl.className = "book-title";
      titleEl.textContent = book.title;

      const authorEl = document.createElement("p");
      authorEl.className = "book-author";
      authorEl.textContent = book.author;

      contentDiv.appendChild(titleEl);
      contentDiv.appendChild(authorEl);

      const yearEl = document.createElement("span");
      yearEl.className = "book-year";
      yearEl.textContent = String(book.year);
      yearEl.setAttribute("aria-label", `Published in ${book.year}`);

      card.appendChild(contentDiv);
      card.appendChild(yearEl);
      booksContainer.appendChild(card);
    });
  }
}

searchInput.addEventListener("input", (e) => {
  state.searchQuery = e.target.value;
  renderBooks();
});

sortSelect.addEventListener("change", (e) => {
  state.sortBy = e.target.value;
  renderBooks();
});

orderToggle.addEventListener("click", () => {
  state.ascending = !state.ascending;
  const dirText = state.ascending ? "ASC ▲" : "DESC ▼";
  orderToggle.textContent = dirText;
  orderToggle.setAttribute(
    "aria-label",
    `Toggle sort direction: currently ${state.ascending ? "Ascending" : "Descending"}`
  );
  orderToggle.setAttribute("aria-pressed", String(!state.ascending));
  renderBooks();
});

// Initial Render
renderBooks();
